player_input_config_t *binding =
    (player_input_config_t *)config_p1_move_forward;
player_state_t *player = player_state_table;
do {
    player_input_t &input = player->input;
    input.move_key_forward = binding->move_key_forward;
    input.move_key_backward = binding->move_key_backward;
    input.turn_key_left = binding->turn_key_left;
    input.turn_key_right = binding->turn_key_right;
    input.fire_key = binding->fire_key;
    input.key_reserved_0 = binding->key_reserved_0;
    input.key_reserved_1 = binding->key_reserved_1;
    input.aim_key_left = binding->aim_key_left;
    input.aim_key_right = binding->aim_key_right;
    input.axis_aim_y = binding->axis_aim_y;
    input.axis_aim_x = binding->axis_aim_x;
    input.axis_move_y = binding->axis_move_y;
    input.axis_move_x = binding->axis_move_x;
    ++binding;
    ++player;
} while ((int)binding
    < (int)((player_input_config_t *)config_p1_move_forward + 2));

player_input_config_t *binding =
    (player_input_config_t *)config_p1_move_forward;
int *runtime_move_backward =
    &player_state_table[0].input.move_key_backward;
do {
    runtime_move_backward[-1] = binding->move_key_forward;
    runtime_move_backward[0] = binding->move_key_backward;
    runtime_move_backward[1] = binding->turn_key_left;
    runtime_move_backward[2] = binding->turn_key_right;
    runtime_move_backward[3] = binding->fire_key;
    runtime_move_backward[4] = binding->key_reserved_0;
    runtime_move_backward[5] = binding->key_reserved_1;
    runtime_move_backward[6] = binding->aim_key_left;
    runtime_move_backward[7] = binding->aim_key_right;
    runtime_move_backward[9] = binding->axis_aim_y;
    runtime_move_backward[8] = binding->axis_aim_x;
    runtime_move_backward[11] = binding->axis_move_y;
    runtime_move_backward[10] = binding->axis_move_x;
    ++binding;
    runtime_move_backward += sizeof(player_state_t) / sizeof(int);
} while ((int)binding
    < (int)((player_input_config_t *)config_p1_move_forward + 2));

